Suppose Assumptions~3.1,~4.1–4.4 hold. Let $d=mn$ be the number of trainable parameters, consider the Quantized Adam algorithm defined in alg:framework run for $T$ iterations with $\eta_t = (1 - \beta_1) \Omega_t \eta$, where $\Omega_t = \sqrt{\sum_{j=0}^{t-1} \beta_2^j}$. Suppose $\beta_1^2(1+q_M)^2 < \beta_2(1-q_V)$, $\beta_1(1+q_M) < \beta_2(1-q_V)$, and $2\beta_1/(1-\beta_1)\le T$, then for an iteration index $\tau$ chosen randomly from $\{0, \dots, T-1\}$ with $P(\tau=j) \propto (1 - \beta_1^{T-j})$, we have:

\begin{align*}

    &\mathbb{E}\left[\|\nabla F(\mathbf{W}_{\tau})\|_F^2\right] \leq
    4 (1+q_G)R \frac{F_0 - F_*}{\eta T}+\frac{\tilde{Q}(T)}{T} + \frac{2q_W T\eta\cdot (1-\beta_1)d^\frac{3}{2} \eta  L (1+q_G)R^2 }{\sqrt{\epsilon}(1-\beta_2)\sqrt{1-\frac{\beta_1^2(1+q_M)^2}{\beta_2(1-q_V)}}} \\

    &+\frac{4(1+q_G) d }{\sqrt{\epsilon(1-\beta_2)}} \left( q_G R^3 + L q_W R^2 D \right) + \frac{C}{T}\left(\ln\left(1 + \frac{((1+q_G)R)^2}{\epsilon(1-\beta_2(1-q_V))}\right) - T\ln(\beta_2(1-q_V))\right) ,
\end{align*}
where $C$ is a constant depending on the problem hyperparameters, and $\tilde Q(T)$ is a function with respect to $T$, $q_V$, $q_G$, and $q_M$, which approaches zero when $q_V, q_M\rightarrow 0$ (please refer to Eq~A.43 for their detailed formula).


Moreover, by setting $\eta=\Theta(1/\sqrt{T})$, $1-\beta_2=\Theta(1/T)$, $q_G = \mathcal{O}(1/T)$, $q_M = \mathcal{O}(1/T)$, $q_V = \mathcal{O}(1/T^2)$, $q_W = \mathcal{O}(1/T^2)$, then $\tilde Q(T)/T = \mathcal{O}(T^{-1/2})$ (refer to Eq.~A.44 for calculation details) and
    \begin{align*}
        \mathbb{E}[\|\nabla F(\mathbf{W}_{\tau})\|_F] = \tilde{\mathcal{O}}\left(T^{-1/4}\right).
    \end{align*}

Suppose Assumptions~3.1,~4.1–4.4 hold. Consider the Quantized Muon algorithm in alg:framework and~alg:muon run for $T$ iterations with $\eta_t=\eta,\beta(1+q_M) < 1$, then
    \begin{align*}
        \frac{1}{T}\sum_{t=0}^{T-1}\mathbb{E}[\| \nabla F(\mathbf{W}_t) \|_F] 
        &\le \frac{\mathbb{E}[F(\mathbf{W}_0)-F(\mathbf{W}_T)]}{\eta T} + \frac{2\beta L\eta r}{1-\beta} + \frac{6\sigma\sqrt{r}}{T(1-\beta)\sqrt{B}}+ \sqrt{\frac{1-\beta}{1+\beta}}\frac{6\sigma\sqrt{r}}{\sqrt{B}} + \\ 
        &\frac{L\eta r}{2} + C_{2}\cdot\bigg(q_G+ q_W + q_G T\eta + q_W T\eta + \frac{q_M\beta}{1-\beta(1+q_M)}(1+T\eta) \bigg) ,
    \end{align*}
    where $C_2$ is absolute constant, $r=\min\{m,n\}$.
    Moreover, suppose $F(\mathbf{W}_0) - F^* \le \Delta$ for constant $\Delta > 0$, set $1-\beta = \Theta(T^{-1/2})$, $\eta = \Theta(T^{-3/4})$, and $B = 1$, if $q_G = q_W = q_M = \mathcal{O}(T^{-1/2})$, then
    \begin{align*}
        \frac{1}{T}\sum_{t=0}^{T-1}\mathbb{E}[\| \nabla F(\mathbf{W}_t) \|_F] = \mathcal{O}(T^{-1/4}).
    \end{align*}

The expectation of term C, defined in (A.20), is lower-bounded by:
\begin{align}

    \mathbb{E}\left[C\right] &\geq \frac{1}{2}\left(\sum_{i\in [d]} \sum_{k=0}^{t-1}\beta_1^k\mathbb{E}\left[\frac{\mathcal{G}_{t - k, i}^2}{\sqrt{\epsilon+\tilde{v}_{t, k+1, i}}}\right]\right) -
    \frac{2 (1+q_G)R}{\sqrt{1 - \beta_1}}\left(\sum_{i\in [d]} \sum_{k=0}^{t-1}
     \left(\frac{\beta_1}{\beta_2}\right)^k \sqrt{k+1} \mathbb{E}\left[\|\mathbf{U}_{t -k}\|_2^2\right]\right)\\
     &\quad-d\sum_{k=0}^{t-1}\beta_1^kM_{t-k}.
\end{align}
where $M_{t-k} = \frac{q_GR^2+Lq_WR\|\mathbf{w}_{t-k-1}\|_2}{\sqrt{\epsilon}}$.

Under the condition that $\beta_1(1+q_M) < \beta_2(1-q_V)$, the expected sum of squared updates over $T$ iterations is bounded by:
\begin{align}
    \sum_{t=1}^T\mathbb{E}\left[\|\mathbf{u}_t\|^2_2\right] &\le \frac{d}{(1 - \beta_1(1+q_M))(1 - \frac{\beta_1(1+q_M)}{\beta_2(1-q_V)})}  \\ 
    &\quad \times \left(\ln\left(1 + \frac{((1+q_G)R)^2}{\epsilon(1-\beta_2(1-q_V))}\right) - T\ln(\beta_2(1-q_V))\right). 
\end{align}

The term M, representing the accumulated quantization bias from (A.26), is bounded by:
\begin{align}
    M \le \frac{\eta_T d T}{\sqrt{\epsilon}(1-\beta_1)} \left( q_G R^2 + L q_W R \|\mathbf{w}_0\|_2 \right) + \frac{\eta_T^2 d L q_W UR T^2}{2\sqrt{\epsilon}(1-\beta_1)},
\end{align}
where $U = \sqrt{\frac{d}{1-\frac{\beta_1^2(1+q_M)^2}{\beta_2(1-q_V)}}}$.

Let $LB_{t,i} = \sum_{k=0}^t\beta_2^{t-k}(1-q_V)^{t-k}(\nabla_i f_k(\mathbf{w}_{k-1}) + \delta_{k,i})^2$ and $UB_{t,i} = \sum_{k=0}^t\beta_2^{t-k}(1+q_V)^{t-k}(\nabla_i f_k(\mathbf{w}_{k-1}) + \delta_{k,i})^2$. We have:
\begin{align}
    \sum_{k=0}^t\beta_2^{t-k}(1-q_V)^{t-k}(\nabla_i f_k(\mathbf{w}_{k-1}) + \delta_{k,i})^2 \le v_{t, i} \le \sum_{k=0}^t\beta_2^{t-k}(1+q_V)^{t-k}(\nabla_i f_k(\mathbf{w}_{k-1}) + \delta_{k,i})^2
\end{align}
\begin{align}
    \left|\frac{1}{\sqrt{\epsilon+v_{t,i}}}-\frac{1}{\sqrt{\epsilon+v'_{t,i}}}\right| \le \max\left\{ \frac{1}{\sqrt{\epsilon+LB_{t,i}}} - \frac{1}{\sqrt{\epsilon+v'_{t,i}}}, \frac{1}{\sqrt{\epsilon+v'_{t,i}}} - \frac{1}{\sqrt{\epsilon+UB_{t,i}}} \right\}
\end{align}

Given two discrete-time systems defined for \( t \ge 1 \):
\begin{itemize}
    \item System A: \( a_{t}=k(a_{t-1}+c_{t-1})+d_{t} \)
    \item System B: \( b_{t}=kb_{t-1}+d_{t} \)
\end{itemize}
where the perturbation term \( c_t \) is bounded by \( |c_{t}|\le q|a_{t}| \) for all \( t \), and the constants \( k, q \) satisfy \( 0<k<1 \) and \( q<k \).

Under zero initial conditions, where \( a_0 = b_0 = 0 \), the absolute error between the states of the two systems is bounded by:
\begin{align}
    |a_{t}-b_{t}|\le\sum_{j=1}^{t-1}\left[(k(1+q))^{t-j}-k^{t-j}\right]|d_{j}|
\end{align}

For any scalar $\rho \in (0, 1)$ and any integer $K \in \mathbb{N}$, the following bound holds:
\begin{equation}

    \sum_{k = 0}^{K - 1} \rho^k \sqrt{k} (k + 1)
    \leq \frac{4 \rho}{(1 - \rho)^{5/2}}.
\end{equation}

The term D, which captures the error from gradient drift as defined in (A.20), is bounded by:
\begin{align}
|D| \leq \frac{\eta_t^2 L^2 \sqrt{1 - \beta_1}}{4 (1+q_G)R}\left( \sum_{l=1}^{t-1}\|\mathbf{u}_{t-l}\|_2^2\sum_{k=l}^{t - 1}\beta_1^k \sqrt{k} \right)
+\frac{(1+q_G)R}{\sqrt{1 - \beta_1}} \sum_{k=0}^{t-1} \left(\frac{\beta_1}{\beta_2}\right)^k \sqrt{k+1}\|\mathbf{U}_{t-k}\|_2^2.
\end{align}

For any scalar $\rho \in (0, 1)$ and any integer $K \in \mathbb{N}$, the following bound holds for the finite geometric sum:
\begin{equation}

    \sum_{k = 0}^{K - 1} \rho^k \sqrt{k + 1}  
    \leq \frac{2}{(1 - \rho)^{3/2}}.
\end{equation}

Let the stochastic gradient be bounded in infinity norm almost surely by $\|\nabla f_t(\mathbf{w}; \gamma)\|_\infty \le R - \sqrt{\epsilon}$ for any parameters $\mathbf{w}$. Let the gradient quantization operator satisfy the relative error model $|Q(z) - z| \le q_G|z|$ for any scalar $z$. The quantized gradient estimator $\hat{\mathbf{g}_t}$ is defined component-wise for $i \in [d]$ as:
\begin{align}
    \hat{g}_{t,i} = \frac{1}{B}\sum_{j=1}^{B} [\nabla^Q f(\mathbf{w}_{t-1}^Q; \gamma_{t,j})]_i,
\end{align}
where we use $\nabla^Q f(\cdot)$ as shorthand for $Q(\nabla f(\cdot))$ and $[\cdot]_i$ to denote the i-th component. Then, the infinity norm of the estimator is bounded almost surely:
\begin{align}
    \|\hat{\mathbf{g}_t}\|_\infty \le (1+q_G)(R - \sqrt{\epsilon}).
\end{align}
For notational simplicity in subsequent proofs, we will use the slightly looser bound $\|\hat{\mathbf{g}_t}\|_\infty \le (1+q_G)R$.

Let \((g_k)_{k=0}^t\) be a sequence of scalars for any finite \(t \in \mathbb{N}\). Let the weights be terms of two geometric series, \(A_k = a^k\) and \(B_k = b^k\), where \(a, b \in (0, 1)\) are the base ratios.

If the condition \(a^2 < b\) holds, then the ratio of the weighted sum is bounded by a constant derived from the corresponding infinite series:
\begin{align}
    \frac{\sum_{k=0}^{t} a^k |g_k|}{\sqrt{\sum_{k=0}^{t} b^k g_k^2}} \le \sqrt{\frac{1}{1 - a^2/b}} 
\end{align}

Suppose Assumptions~4.1,~4.2,~4.3 and 3.1 hold. For any $t\ge 0$, if $\beta(1+q_M)<1$, we have
    \begin{align*}
        \mathbb{E}[\| \mathbf{Z}_t - \mathbf{M}_t \|_F] \le& \frac{q_M\beta}{1-\beta(1+q_M)}\bigg( \frac{\sigma}{\sqrt{B}} + \sqrt{\frac{1-\beta}{1+\beta}}\cdot\frac{\sigma}{\sqrt{B}} + G + q_G(\sigma + G) +  \bigg.\\
        &\bigg. q_W (1+q_G)DL + (1+q_W)(1+q_G)t\eta\sqrt{r}L \bigg).
    \end{align*}

Suppose Assumptions~4.1,~4.2 and 3.1 hold. For any $t\ge 0$, we have
    \begin{align*}
        \mathbb{E}[\|\mathbf{X}_t - \mathbf{Y}_t\|_F] \le q_G(\sigma + G + t\eta\sqrt{r}L).
    \end{align*}

Suppose Assumptions~4.3 and 4.4 hold. For any $t\ge 0$, we have
    \begin{align*}
        \mathbb{E}[\|\nabla F(\mathbf{W}_t)-\mathbf{C}_t\|_F] \le \frac{\beta L \eta \sqrt{r}}{1-\beta}.
    \end{align*}

Suppose Assumptions~4.1 and~4.2 hold. For any $t\ge 0$, we have
    \begin{align*}
        \mathbb{E}[\|\mathbf{C}_t - \mathbf{X}_t\|_F] \le \beta^t\frac{\sigma}{\sqrt{B}} + \sqrt{\frac{1-\beta}{1+\beta}}\frac{\sigma}{\sqrt{B}}.
    \end{align*}

Suppose Assumptions~4.3 and 4.4 hold. The iterates of Muon satisfy that for any $t\ge 0$,
    \begin{align*}
        \|\mathbf{W}_t\|_F \le D+t\eta\sqrt{r},\quad \|\nabla F(\mathbf{W}_t)\|_F \le G + t\eta\sqrt{r}L.
    \end{align*}

Suppose Assumption~3.1 holds. For any matrix $\mathbf{X}\in\mathbb{R}^{m\times n}$ and its quantized version $\mathbf{X}^Q$, we have
    \begin{align*}
        \|\mathbf{X}^{Q} - \mathbf{X}\|_F \le q\|\mathbf{X}\|_F.
    \end{align*}
